#!/usr/bin/env bash
# Pi-hole's blocklist for gate.home — generated by kiwi-server, run by km-pihole-blocklist.timer.
#
# Pi-hole fetches its blocklist when its container starts, before it answers names
# itself. On a machine whose own lookups go through this Pi-hole the fetch found no
# name, the list stayed empty, and the ad blocker blocked nothing, without a word.
# Looked at soon after every start and once an hour: an empty list is fetched again.
set -u
C="km-pihole"
RT="podman"
count() { "$RT" exec "$C" pihole-FTL sqlite3 /etc/pihole/gravity.db "select count(*) from gravity" 2>/dev/null | tr -dc '0-9'; }
n=$(count)
[[ ${n:-0} -gt 0 ]] && exit 0
"$RT" exec "$C" true 2>/dev/null || exit 0          # not running: nothing to look at
echo "[kiwi-dns] Pi-hole's blocklist is empty: fetching it"
"$RT" exec "$C" pihole -g >/dev/null 2>&1
n=$(count)
if [[ ${n:-0} -gt 0 ]]; then
    echo "[kiwi-dns] $n domains are blocked now"
else
    echo "[kiwi-dns] the blocklist could not be fetched (no Internet from the container yet?): the next try is in an hour"
    exit 1
fi
